public class Main {
    static int fleetTrips = 0;

    static class Drone {
        int fuel;
        Drone(int fuel) { this.fuel = fuel; }
        void fly(int distance) {
            fuel -= distance / 10;
            fleetTrips++;
        }
    }

    public static void main(String[] args) {
        Drone a = new Drone(100);
        Drone b = a;
        Drone c = new Drone(100);

        a.fly(30);
        b.fly(20);
        c.fly(50);

        System.out.println(a.fuel);
        System.out.println(c.fuel);
        System.out.println(fleetTrips);
    }
}

