public class WeeklyReading {
    private int[] pages;

    public WeeklyReading(int[] pages) {
        this.pages = pages;
    }

    public int totalPages() {
        int sum = 0;
        for (int i = 0; i < pages.length; i++) {
            sum += pages[i];
        }
        return sum;
    }

    public int daysMetGoal(int goal) {
        int count = 0;
        for (int i = 0; i < pages.length; i++) {
            if (pages[i] > goal) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        WeeklyReading week = new WeeklyReading(new int[]{20, 30, 30, 15, 40, 30, 10});
        System.out.println("Total: " + week.totalPages());
        System.out.println("Days met goal of 30: " + week.daysMetGoal(30));
    }
}

